    import sys
    input = sys.stdin.read
    data = input().strip().split()

    t = int(data[0])
    results = []

    def will_vanya_win(n):
        return n % 3 != 0

    for i in range(1, t + 1):
        n = int(data[i])
        if will_vanya_win(n):
            results.append("First")
        else:
            results.append("Second")

    print("\n".join(results))

