def solve():
    import sys

    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1

    results = []

    for _ in range(t):
        n = int(data[index])
        k = int(data[index + 1])
        s = data[index + 2]
        index += 3

        count_B = s.count('B')

        if count_B == k:
            results.append('0')
        else:
            operations = []
            if count_B < k:
                # Need to add (k - count_B) B's
                extra_B = k - count_B
                for i in range(n):
                    if s[i] == 'A':
                        extra_B -= 1
                        operations.append((i + 1, 'B'))
                        if extra_B == 0:
                            break
            else:
                # Need to convert (count_B - k) B's to A's
                excess_B = count_B - k
                for i in range(n - 1, -1, -1):
                    if s[i] == 'B':
                        excess_B -= 1
                        operations.append((i + 1, 'A'))
                        if excess_B == 0:
                            break

            results.append(str(len(operations)))
            for op in operations:
                results.append(f"{op[0]} {op[1]}")

    print("\n".join(results))
