def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    results = []
    for i in range(1, t + 1):
        n = int(data[i])

        if n < 6 or n == 9:
            results.append("NO")
        else:
            if n % 3 == 0:
                # Pick three numbers not divisible by 3, total should sum to `n`.
                if n >= 8:
                    results.append("YES")
                    results.append(f"2 5 {n - 7}")  # As 2, 5 are not divisible by 3 and 2 + 5 + k gives n
                else:
                    results.append("NO")
            elif n % 3 == 1:
                # n % 3 = 1 implies n = 3k + 1
                if n >= 7:
                    results.append("YES")
                    results.append(f"1 5 {n - 6}")  # As 1, 5 are not divisible by 3 and 1 + 5 + k gives n
                else:
                    results.append("NO")
            elif n % 3 == 2:
                # n % 3 = 2 implies n = 3k + 2
                if n >= 8:
                    results.append("YES")
                    results.append(f"2 4 {n - 6}")  # As 2, 4 are not divisible by 3 and 2 + 4 + k gives n
                else:
                    results.append("NO")

    sys.stdout.write("\n".join(results) + "\n")
```

This code uses the logic that numbers that are not divisible by 3 can be used to create solutions according to different values of `n % 3`:

- If `n % 3 == 0` and `n >= 8`: triplet can be `2, 5, n-7`.
- If `n % 3 == 1` and `n >= 7`: triplet can be `1, 5, n-6`.
- If `n % 3 == 2` and `n >= 8`: triplet can be `2, 4, n-6`.

If `n` is too small to form a sum of three distinct numbers or if an immediate check such as `n = 9` makes it impossible, the output is "NO".

