def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        k = int(data[index + 1])
        index += 2
        a = list(map(int, data[index:index + n]))
        index += n

        if n == 1:
            # If the array has only one element and it's k, then the answer is "YES"
            if a[0] == k:
                results.append("YES")
            else:
                results.append("NO")
            continue

        # We need to check if k is the most common element on any subsegment
        # Thus, there must be at least two occurrences of k in the array to form a subsegment
        exists = False

        for i in range(n):
            if a[i] == k:
                # Check for at least one more k around it directly
                if i > 0 and a[i - 1] == k:
                    exists = True
                    break
                if i < n - 1 and a[i + 1] == k:
                    exists = True
                    break

        # If exists is still not True, check if at least two occurrences of k with any intervening elements
        if not exists:
            count_k = 0
            for i in range(n):
                if a[i] == k:
                    count_k += 1
                    if count_k >= 2:
                        exists = True
                        break

        if exists:
            results.append("YES")
        else:
            results.append("NO")

    print("\n".join(results))
