def solve():
    import sys
    input = sys.stdin.read
    data = input().strip().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n, k = int(data[index]), int(data[index + 1])
        index += 2
        a = list(map(int, data[index:index + n]))
        index += n

        possible = 'NO'

        counts = {}
        for number in a:
            counts[number] = counts.get(number, 0) + 1

        if counts.get(k, 0) > 0:
            if counts[k] > max(count for number, count in counts.items() if number != k):
                possible = 'YES'
            elif counts[k] > 1:
                # Special case: if k appears more than once, it can always form the majority in a segment by selecting only ks
                possible = 'YES'
            else:
                # Check pairs of consecutive k values
                for i in range(n - 1):
                    if a[i] == k and a[i + 1] == k:
                        possible = 'YES'
                        break

        results.append(possible)

    print('\n'.join(results))
