def solve():
    import sys

    input = sys.stdin.read
    data = input().splitlines()

    point_values = [
        (0, 9, 1), (1, 8, 2),
        (2, 7, 3), (3, 6, 4),
        (4, 5, 5)
    ]

    t = int(data[0])
    result = []
    index = 1

    for _ in range(t):
        score = 0
        for i in range(10):
            line = data[index + i]
            for j in range(10):
                if line[j] == 'X':
                    for (low, high, points) in point_values:
                        if low <= i <= high and low <= j <= high:
                            score += points
                            break
        result.append(score)
        index += 10

    for res in result:
        print(res)

