            if num == x:
                continue
            if current_sum + num <= n:
                nums.append(num)
                current_sum += num
            if current_sum == n:
                break

        if current_sum != n:
            results.append("NO")
        else:
            results.append("YES")
            results.append(str(len(nums)))
            results.append(' '.join(map(str, nums)))

