def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    t = int(data[index])
    index += 1
    results = []

    for _ in range(t):
        n = int(data[index])
        k = int(data[index + 1])
        index += 2

        opinions = []
        for _ in range(n):
            opinions.append(data[index])
            index += 1

        max_members = 1  # Minimum is 1, since the president must remain.

        # Loop through each possible subset of the club (using bitmasking)
        for mask in range(1, 1 << (n - 1)):
            # Include the yourself (member 1) always
            current_members = [0]
            for i in range(n - 1):
                if (mask & (1 << i)) != 0:
                    current_members.append(i + 1)

            remaining = set(current_members)

            for j in range(k):
                Y = 0
                N = 0
                for mem in current_members:
                    if opinions[mem][j] == '+':
                        Y += 1
                    else:
                        N += 1

                if Y > N:
                    # All who disagree leave
                    remaining = {mem for mem in remaining if opinions[mem][j] == '+'}
                elif Y < N:
                    # All who agree leave
                    remaining = {mem for mem in remaining if opinions[mem][j] == '-'}
                else:
                    # All leave in case of tie
                    remaining = set()

                if 0 not in remaining:
                    # If you left, invalidate this combination
                    break

            if 0 in remaining:
                max_members = max(max_members, len(remaining))

        results.append(str(max_members))

    print("\n".join(results))

