                N = 0
                for mem in current_members:
                    if opinions[mem][j] == '+':
                        Y += 1
                    else:
                        N += 1

                if Y > N:
                    # All who disagree leave
                    remaining = {mem for mem in remaining if opinions[mem][j] == '+'}
                elif Y < N:
                    # All who agree leave
                    remaining = {mem for mem in remaining if opinions[mem][j] == '-'}
                else:
                    # All leave in case of tie
                    remaining = set()

                if 0 not in remaining:
                    # If you left, invalidate this combination
                    break

            if 0 in remaining:
                max_members = max(max_members, len(remaining))

        results.append(str(max_members))

    print("\n".join(results))

