def solve():
    import sys

    read = sys.stdin.read
    data = read().strip().split('\n')

    t = int(data[0])
    results = []

    def compare_sizes(a, b):
        val_a = (len(a) - 1, a[-1])
        val_b = (len(b) - 1, b[-1])

        # Define an ordering for the types S, M, L
        rank = {'S': 0, 'M': 1, 'L': 2}

        if val_a[1] == val_b[1]:
            if val_a[1] == 'S':
                return '<' if val_a[0] > val_b[0] else ('=' if val_a[0] == val_b[0] else '>')
            else:  # val_a[1] == 'L'
                return '>' if val_a[0] > val_b[0] else ('=' if val_a[0] == val_b[0] else '<')
        else:
            return '<' if rank[val_a[1]] < rank[val_b[1]] else '>'

    for i in range(1, t + 1):
