def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    primes = set()

    def is_prime(x):
        if x <= 1:
            return False
        if x <= 3:
            return True
        if x % 2 == 0 or x % 3 == 0:
            return False
        i = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return False
            i += 6
        return True

    # Precompute prime numbers up to 10^5
    for num in range(2, 100001):
        if is_prime(num):
            primes.add(num)

    # Parsing the input
    t = int(data[0])
    results = []

    for i in range(1, t + 1):
        n = int(data[i])

        # Find the smallest m starting from 2 such that n + m is not prime
        # We choose 2 because first composite number we get is 9 with n + 2
        # Given the constraints this will work in all circumstances.
        m = 2
        while (n + m) in primes:
            m += 1

        results.append(m)

    # Print all results
    sys.stdout.write("\n".join(map(str, results)) + "\n")

